package com.rumitx.app;
import android.app.*;import android.widget.*;import android.view.*;
public final class TonePicker {
 public interface Selection {void apply(double hz,String dcs);}
 public static void show(Activity a,double initialHz,String initialDcs,Selection done){LinearLayout box=new LinearLayout(a);box.setOrientation(1);box.setPadding(24,12,24,12);box.setBackgroundColor(0xff050508);Spinner mode=new Spinner(a),values=new Spinner(a);TextView index=new TextView(a);index.setTextColor(0xff00f0ff);index.setPadding(8,16,8,16);Switch inverse=new Switch(a);inverse.setText("DCS inverted");inverse.setChecked(initialDcs!=null&&initialDcs.toUpperCase(java.util.Locale.US).endsWith("I"));box.addView(mode);box.addView(values);box.addView(inverse);box.addView(index);mode.setMinimumHeight(48);values.setMinimumHeight(48);mode.setAdapter(new ArrayAdapter<String>(a,android.R.layout.simple_spinner_dropdown_item,new String[]{"CTCSS","DCS"}));final boolean[] first={true};mode.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int position,long id){boolean d=position==1;String[] labels=new String[(d?ToneIndex.DCS.length:ToneIndex.CTCSS.length)+1];labels[0]="None (0)";for(int i=1;i<labels.length;i++)labels[i]=(d?ToneIndex.DCS[i-1]:String.format(java.util.Locale.US,"%.1f Hz",ToneIndex.CTCSS[i-1]))+" ("+i+")";values.setAdapter(new ArrayAdapter<String>(a,android.R.layout.simple_spinner_dropdown_item,labels));inverse.setVisibility(d?View.VISIBLE:View.GONE);int selected=0;if(first[0]){try{selected=d?ToneIndex.dcs(initialDcs):ToneIndex.ctcss(initialHz);}catch(IllegalArgumentException ignored){}first[0]=false;}values.setSelection(selected);}});values.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int n,long id){index.setText("Module will use index "+n);}});mode.setSelection(ToneIndex.normalize(initialDcs).isEmpty()?0:1);new AlertDialog.Builder(a).setTitle("PL / DCS tone · TX + RX").setView(box).setNegativeButton("Cancel",null).setPositiveButton("Use tone",(d,w)->{int n=values.getSelectedItemPosition();boolean dc=mode.getSelectedItemPosition()==1;done.apply(!dc&&n>0?ToneIndex.CTCSS[n-1]:0,dc&&n>0?ToneIndex.DCS[n-1]+(inverse.isChecked()?"I":""):"");}).show();}
}
